import sys,difflib,re
lines=open(sys.argv[1],encoding='utf-8').read().split('\n')
i=0;minus=[];plus=[]
def flush():
    global minus,plus
    if minus or plus:
        a=' '.join(minus);b=' '.join(plus)
        ta=re.findall(r'\S+|\s+',a);tb=re.findall(r'\S+|\s+',b)
        sm=difflib.SequenceMatcher(None,ta,tb,autojunk=False)
        out=[]
        for op,i1,i2,j1,j2 in sm.get_opcodes():
            if op=='equal':
                t=''.join(ta[i1:i2])
                out.append(t if len(t)<160 else t[:70]+' ... '+t[-70:])
            else:
                if i2>i1: out.append('[-'+''.join(ta[i1:i2])+'-]')
                if j2>j1: out.append('{+'+''.join(tb[j1:j2])+'+}')
        print(''.join(out));print('-----')
    minus=[];plus=[]
for l in lines:
    if l.startswith('@@'):
        flush();print('\n'+l[:80])
    elif l.startswith('-') and not l.startswith('---'): minus.append(l[1:])
    elif l.startswith('+') and not l.startswith('+++'): plus.append(l[1:])
    else: flush()
flush()
EOF
python /tmp/wd.py "$F" > /tmp/wd.out 2>&1; wc -c /tmp/wd.out; head -c 15000 /tmp/wd.out

